const DATA={"saki_idle": "data:image/png;base64,", "saki_run": "data:image/png;base64,", "saki_atk": "data:image/png;base64,", "saki_jump": "data:image/png;base64,", "zombie": "data:image/png;base64,", "skeleton": "data:image/png;base64,"};
'use strict';
const cv=document.getElementById('c'),ctx=cv.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=800,H=450,GY=380,LEN=3200;
const P1='#a020f0',CY='#00e5ff';
const STAGES=[
 {n:'Floresta Neon',b:'Guardião de Pedra',bg:['#041510','#0f4030'],ac:'#40ffa0',bc:'#8a8a9a',hp:14,sp:1.2,shoot:0,dash:1},
 {n:'Castelo Arruinado',b:'Verme Cristalino',bg:['#120826','#34265a'],ac:'#c080ff',bc:'#38d8c8',hp:16,sp:1.4,shoot:1,dash:0,sink:1},
 {n:'Cemitério Assombrado',b:'Andróide Defeituoso',bg:['#070d18','#233048'],ac:'#80ffd0',bc:'#e0e040',hp:18,sp:2.2,shoot:2,dash:0},
 {n:'Salão do Trono Corrompido',b:'Cavaleiro Sombrio',bg:['#1f0710','#4a1030'],ac:'#ff4060',bc:'#40304a',hp:24,sp:1.8,shoot:1,dash:1},
 {n:'O Núcleo do Mal',b:'Soberano do Núcleo',bg:['#000010','#1a0040'],ac:'#ffffff',bc:'#d010a0',hp:44,sp:2,shoot:2,dash:1,final:1}
];
const loadHi=()=>{try{return +localStorage.getItem('sakiHi')||0;}catch(e){return 0;}};
const saveHi=()=>{try{localStorage.setItem('sakiHi',hi);}catch(e){}};
let hi=loadHi();
let state='menu',stage=0,score=0,lives=3,wlv=1,cam=0,t=0,msgT=0;
let pl,en,orbs,bul,disk,boss,parts,spawnX,bossOn;

/* ---------- Áudio chiptune (efeitos + música procedural) ---------- */
let ac=null,mg=null,mute=false;
function initAudio(){try{ac=ac||new AudioContext();if(!mg){mg=ac.createGain();mg.gain.value=mute?0:1;mg.connect(ac.destination);}if(ac.state==='suspended')ac.resume();return true;}catch(e){return false;}}
function snd(f,d=.1,type='square',v=.05){if(!initAudio())return;const n=ac.currentTime,o=ac.createOscillator(),g=ac.createGain();o.type=type;
 o.frequency.setValueAtTime(f,n);o.frequency.exponentialRampToValueAtTime(type==='sawtooth'?f*.45:f*1.7,n+d);
 g.gain.setValueAtTime(v,n);g.gain.exponentialRampToValueAtTime(.0001,n+d);o.connect(g);g.connect(mg);o.start(n);o.stop(n+d);}
function tone(f,t,d,type,v){const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(mg);o.start(t);o.stop(t+d+.02);}
function noiseHit(t,d,v){const len=ac.sampleRate*d|0,b=ac.createBuffer(1,len,ac.sampleRate),a=b.getChannelData(0);for(let i=0;i<len;i++)a[i]=(Math.random()*2-1)*(1-i/len);const s=ac.createBufferSource(),g=ac.createGain();s.buffer=b;g.gain.value=v;s.connect(g);g.connect(mg);s.start(t);}
function swordSwing(){if(!initAudio())return;const n=ac.currentTime,d=.2,len=ac.sampleRate*d|0,b=ac.createBuffer(1,len,ac.sampleRate),a=b.getChannelData(0);for(let i=0;i<len;i++)a[i]=Math.random()*2-1;
 const s=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();s.buffer=b;f.type='bandpass';f.Q.value=2.5;f.frequency.setValueAtTime(500,n);f.frequency.exponentialRampToValueAtTime(3800,n+d);
 g.gain.setValueAtTime(.0001,n);g.gain.exponentialRampToValueAtTime(.35,n+.06);g.gain.exponentialRampToValueAtTime(.0001,n+d);s.connect(f);f.connect(g);g.connect(mg);s.start(n);}
function swordHit(){if(!initAudio())return;const n=ac.currentTime;for(const [f,v] of [[1900,.07],[2850,.05],[4300,.03]]){const o=ac.createOscillator(),g=ac.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(v,n);g.gain.exponentialRampToValueAtTime(.0001,n+.22);o.connect(g);g.connect(mg);o.start(n);o.stop(n+.24);}noiseHit(n,.05,.25);}
const BPM=[148,136,158,144,168],ROOT=[57,55,52,50,48];
const LEAD=[12,15,19,15,12,15,19,22,24,22,19,15,12,10,12,15,12,15,19,15,12,15,19,22,27,24,22,19,17,15,14,10];
const BASS=[0,0,12,0,0,0,12,0,-2,-2,10,-2,-5,-5,7,-5];
const hz=m=>440*Math.pow(2,(m-69)/12);
let mstep=0,mnext=0,mtimer=null;
function musicStep(i,t,sp){
 const r=ROOT[Math.min(stage,4)],k=i%16,ld=LEAD[i%32];
 tone(hz(r+BASS[k]-12),t,sp*.9,'triangle',.11);
 tone(hz(r+ld),t,sp*.85,'square',.035);
 if(bossOn&&i%2)tone(hz(r+ld+7),t,sp*.4,'square',.02);
 if(k%4===0){const o=ac.createOscillator(),g=ac.createGain();o.frequency.setValueAtTime(150,t);o.frequency.exponentialRampToValueAtTime(40,t+.12);g.gain.setValueAtTime(.25,t);g.gain.exponentialRampToValueAtTime(.0001,t+.14);o.connect(g);g.connect(mg);o.start(t);o.stop(t+.15);}
 if(k===4||k===12)noiseHit(t,.12,.16);else if(i%2===0)noiseHit(t,.03,.04);
}
function musicTick(){if(!ac)return;if(mnext<ac.currentTime)mnext=ac.currentTime+.05;
 while(mnext<ac.currentTime+.2){const sp=60/(BPM[Math.min(stage,4)]*(bossOn?1.12:1))/4;if(state==='play')musicStep(mstep,mnext,sp);mnext+=sp;mstep++;}}
function startMusic(){if(!initAudio())return;if(!mtimer)mtimer=setInterval(musicTick,60);}
function fanfare(){if(!initAudio())return;const n=ac.currentTime;[0,4,7,12,16,19,24].forEach((s,i)=>tone(hz(69+s),n+i*.09,.25,'square',.06));}

/* ---------- Entrada ---------- */
const keys={};let prev={j:0,a:0,s:0,p:0};
addEventListener('keydown',e=>{keys[e.code]=1;if(e.code==='KeyM'){mute=!mute;if(mg)mg.gain.value=mute?0:1;}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();});
addEventListener('keyup',e=>keys[e.code]=0);
function input(){
 let l=keys.ArrowLeft||keys.KeyA,r=keys.ArrowRight||keys.KeyD;
 let j=keys.Space||keys.ArrowUp||keys.KeyW,a=keys.KeyX||keys.KeyJ,s=keys.Enter,p=keys.KeyP||keys.Escape;
 let z=keys.KeyZ||keys.KeyK,u=keys.KeyC||keys.KeyL,e=keys.KeyE||keys.ShiftLeft||keys.ShiftRight;
 const gp=(navigator.getGamepads?[...navigator.getGamepads()]:[]).find(g=>g);
 if(gp){const b=i=>gp.buttons[i]&&gp.buttons[i].pressed,ax=gp.axes[0]||0,ay=gp.axes[1]||0;
  l=l||ax<-.4||b(14);r=r||ax>.4||b(15);j=j||b(0)||b(12);a=a||b(2);
  z=z||b(1)||b(5);u=u||b(3)||((b(1)||b(5))&&ay<-.5);e=e||b(4)||b(6)||b(7);s=s||b(9);p=p||b(9);}
 const o={l,r,j:!!j,a:!!a,s:!!s,p:!!p,z:!!z,u:!!u,ep:!!e&&!prev.e,jp:j&&!prev.j,ap:a&&!prev.a,sp:s&&!prev.s,pp:p&&!prev.p};
 prev={j:!!j,a:!!a,s:!!s,p:!!p,e:!!e};return o;
}
const PN=['Shuriken','Leque Triplo','Shuriken Perfurante','Shuriken Explosivo','Chuva de Estrelas (5 shurikens)'];
let shs=[],energy=0,shout=0,flash=0;
function shoutSnd(big){if(!initAudio())return;const n=ac.currentTime,d=big?.55:.2;
 for(const [m,v] of [[1,.07],[1.5,.03]]){const o=ac.createOscillator(),g=ac.createGain();o.type='square';
  o.frequency.setValueAtTime((big?900:760)*m,n);o.frequency.exponentialRampToValueAtTime((big?240:300)*m,n+d);
  if(big){const l=ac.createOscillator(),lg=ac.createGain();l.frequency.value=22;lg.gain.value=40;l.connect(lg);lg.connect(o.frequency);l.start(n);l.stop(n+d);}
  g.gain.setValueAtTime(v,n);g.gain.setValueAtTime(v,n+d*.6);g.gain.exponentialRampToValueAtTime(.0001,n+d);o.connect(g);g.connect(mg);o.start(n);o.stop(n+d);}
 noiseHit(n,.05,.12);}

/* ---------- Início de fase ---------- */
function startStage(){
 pl={x:80,y:GY-42,w:24,h:56,vx:0,vy:0,f:1,hp:3,inv:0,gr:true,cd:0};
 en=[];orbs=[];bul=[];parts=[];shs=[];disk=null;boss=null;bossOn=false;cam=0;spawnX=500;msgT=120;
}
function newGame(){startMusic();stage=0;score=0;lives=3;wlv=1;energy=0;startStage();state='play';snd(660,.2);}
function hurt(d=1){
 if(pl.inv>0)return;pl.hp-=d;pl.inv=100;pl.vy=-5;pl.vx=-pl.f*4;snd(100,.25,'sawtooth');
 if(pl.hp<=0){lives--;if(lives<0){state='over';if(score>hi){hi=score;saveHi();}}else{pl.hp=3;pl.x=Math.max(0,cam+60);pl.y=GY-pl.h;pl.inv=150;wlv=Math.max(1,wlv-1);}}
}
function burst(x,y,col,n=10){for(let i=0;i<n;i++)parts.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.8)*6,l:30,c:col});}
const hit=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;

/* ---------- Atualização ---------- */
function update(){
 const k=input();t++;
 if(state==='menu'){if(k.sp||k.jp||k.ap)newGame();return;}
 if(state==='over'){if(k.sp||k.jp||k.ap)newGame();return;}
 if(state==='win'){if(k.sp||k.jp||k.ap){state='menu';}return;}
 if(state==='pause'){if(k.pp||k.sp)state='play';return;}
 if(state==='clear'){if(--msgT<=0){if(++stage>=5){state='win';if(score>hi){hi=score;saveHi();}}else{startStage();state='play';}}return;}
 if(k.pp){state='pause';return;}
 const S=STAGES[stage];
 // jogadora
 const acc=k.l?-.5:k.r?.5:0;
 if(acc){pl.vx+=acc;pl.f=acc>0?1:-1;}else pl.vx*=.78;
 pl.vx=Math.max(-3.4,Math.min(3.4,pl.vx));
 if(k.jp&&pl.gr){pl.vy=-10.5;pl.gr=false;snd(500,.08);}
 if(!k.j&&pl.vy<-4)pl.vy=-4;
 pl.vy+=.55;pl.x+=pl.vx;pl.y+=pl.vy;
 if(pl.y>=GY-pl.h){pl.y=GY-pl.h;pl.vy=0;pl.gr=true;}
 pl.x=Math.max(0,Math.min(LEN-pl.w,pl.x));
 if(pl.inv>0)pl.inv--;
 cam=Math.max(0,Math.min(LEN-W,pl.x-W/2+pl.w/2));
 // ataque (espada)
 if(k.ap&&!disk){disk={t0:t,hits:new Set(),box:null};swordSwing();}
 if(disk){
  const age=t-disk.t0,reach=[0,50,72,96][wlv];
  if(age>=3&&age<=13){
   const sw={x:pl.f>0?pl.x+pl.w-4:pl.x-reach+4,y:pl.y+6,w:reach,h:pl.h-10};disk.box=sw;
   for(const q of bul)if(hit(sw,q))q.dead=1;
   for(const e of (boss?en.concat([boss]):en)){
    if(e.dead||disk.hits.has(e)||!hit(sw,e))continue;
    if(e.sink&&e.sinkv>25)continue;
    disk.hits.add(e);e.hp-=wlv;e.fl=6;swordHit();
    if(e.hp<=0&&!e.boss)kill(e);
   }
  }else disk.box=null;
  if(age>16)disk=null;
 }
 // shurikens (Z/K reto, C/L para cima) e especial (E/Shift)
 if(pl.cd>0)pl.cd--;
 if((k.z||k.u)&&pl.cd<=0){
  const tier=Math.min(5,stage+1),n=tier>=5?5:tier>=2?3:1;
  for(let i=0;i<n;i++){
   const a=(k.u?-Math.PI/2:(pl.f>0?0:Math.PI))+(i-(n-1)/2)*.22;
   shs.push({x:pl.x+pl.w/2-7,y:pl.y+18,w:14,h:14,vx:Math.cos(a)*9,vy:Math.sin(a)*9,pi:tier>=3,ex:tier>=4,hits:new Set(),r:0});
  }
  pl.cd=16;shout=22;shoutSnd();
 }
 if(k.ep&&energy>=100){
  energy=0;shout=40;flash=16;shoutSnd(true);snd(120,.5,'sawtooth',.1);
  for(const e of en)if(!e.dead&&e.x>cam-20&&e.x<cam+W+20){e.hp-=3;burst(e.x,e.y,'#fff',8);if(e.hp<=0)kill(e);}
  if(boss&&!(boss.sink&&boss.sinkv>25)){boss.hp-=6;boss.fl=8;}
  bul=[];
 }
 if(shout>0)shout--;if(flash>0)flash--;
 for(const s of shs){
  s.x+=s.vx;s.y+=s.vy;s.r+=.5;
  if(s.x<cam-30||s.x>cam+W+30||s.y<30||s.y>GY+10){s.dead=1;continue;}
  for(const e of (boss?en.concat([boss]):en)){
   if(e.dead||s.hits.has(e)||!hit(s,e))continue;
   if(e.sink&&e.sinkv>25)continue;
   s.hits.add(e);e.hp-=1;e.fl=6;snd(420,.06,'sawtooth');
   if(e.hp<=0&&!e.boss)kill(e);
   if(s.ex){burst(s.x,s.y,'#ffb000',14);for(const o of en)if(!o.dead&&o!==e&&Math.abs(o.x-s.x)<70&&Math.abs(o.y-s.y)<70){o.hp-=1;o.fl=6;if(o.hp<=0)kill(o);}}
   if(!s.pi){s.dead=1;break;}
  }
 }
 shs=shs.filter(s=>!s.dead);
 // spawn de inimigos
 if(!bossOn){
  while(spawnX<LEN-W+120&&spawnX<cam+W+60){
   const fly=Math.random()<.4,hp0=fly?1+((stage+1)>>1):2+stage;
   en.push({x:spawnX,y:fly?120+Math.random()*120:GY-46,w:fly?28:30,h:fly?30:46,hp:hp0,mx:hp0,fly,ph:Math.random()*6,stun:0,vx:0,k:fly?'f':'w',sp:.8+stage*.25});
   spawnX+=Math.max(60,170-stage*24)+Math.random()*80;
  }
  if(cam>=LEN-W-1){bossOn=true;boss={x:LEN-160,y:GY-100,w:70,h:100,hp:Math.round(S.hp*1.5),max:Math.round(S.hp*1.5),t:0,dash:0,ph:1,boss:1,sink:S.sink,sinkv:0,f:-1};
   if(S.final){boss.w=90;boss.h=130;boss.y=GY-130;}msgT=100;}
 }
 // inimigos
 for(const e of en){
  if(e.dead)continue;
  if(e.stun>0){e.stun--;}
  else{
   const dir=Math.sign(pl.x-e.x);
   if(e.fly){e.ph+=.05;e.x+=dir*e.sp*.7;e.y+=Math.sin(e.ph)*1.5;}
   else e.x+=dir*e.sp;
  }
  if(e.fl>0)e.fl--;
  if(e.hp<=0)continue;
  if(hit(pl,e)){
   if(!e.fly&&e.stun<=0&&pl.vy>1&&pl.y+pl.h-e.y<18){e.stun=200;pl.vy=-7;score+=50;snd(700,.1);}
   else if(e.stun<=0)hurt();
  }
 }
 en=en.filter(e=>!e.dead&&e.x>cam-200);
 // chefe
 if(boss){
  const b=boss;b.t++;b.f=pl.x<b.x?-1:1;
  b.ph=S.final&&b.hp<b.max/2?2:1;
  if(b.sink){b.sinkv=(Math.sin(b.t/40)+1)*50;b.y=GY-b.h+b.sinkv*.9;}
  if(b.dash>0){b.dash--;b.x+=b.f*(6+b.ph);}
  else{b.x+=b.f*S.sp*.6;}
  const cycle=Math.floor(130/b.ph);
  if(b.t%cycle===0){
   if(S.dash&&Math.random()<.5)b.dash=40;
   else if(S.shoot){
    const n=S.final?(b.ph===2?7:3):S.shoot+1;
    for(let i=0;i<n;i++){const a=S.final&&b.ph===2?(i/n)*Math.PI*2+b.t:Math.atan2(pl.y-b.y,pl.x-b.x)+(i-(n-1)/2)*.25;
     bul.push({x:b.x+b.w/2,y:b.y+30,w:10,h:10,vx:Math.cos(a)*3.2,vy:Math.sin(a)*3.2});}
    snd(250,.12,'sawtooth');
   }
  }
  b.x=Math.max(cam+10,Math.min(LEN-b.w,b.x));
  if(b.fl>0)b.fl--;
  if(hit(pl,b)&&!(b.sink&&b.sinkv>40))hurt();
  if(b.hp<=0){score+=2000+stage*1000;burst(b.x+b.w/2,b.y+b.h/2,S.bc,50);orbs.push({x:b.x,y:GY-20,w:18,h:18});boss=null;bul=[];state='clear';msgT=200;snd(200,.6,'sawtooth');fanfare();fanfare();}
 }
 // projéteis
 for(const q of bul){q.x+=q.vx;q.y+=q.vy;if(hit(pl,q)){q.dead=1;hurt();}if(q.x<cam-20||q.x>cam+W+20||q.y<0||q.y>H)q.dead=1;}
 bul=bul.filter(q=>!q.dead);
 // orbes
 for(const o of orbs){if(hit(pl,o)){o.dead=1;wlv=Math.min(3,wlv+1);score+=200;snd(1000,.2,'triangle');}}
 orbs=orbs.filter(o=>!o.dead);
 for(const p of parts){p.x+=p.vx;p.y+=p.vy;p.vy+=.2;p.l--;}
 parts=parts.filter(p=>p.l>0);
}
function kill(e){
 e.dead=1;if(!e.boss)energy=Math.min(100,energy+10);score+=e.boss?0:100;if(!e.boss){burst(e.x+e.w/2,e.y+e.h/2,e.fly?CY:P1);
  if(Math.random()<(e.fly?.4:.1))orbs.push({x:e.x,y:Math.min(e.y,GY-20),w:18,h:18});}
}

/* ---------- Desenho ---------- */
function bg(S,st=Math.min(stage,4)){
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,S.bg[0]);g.addColorStop(1,S.bg[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 if(st!==3){ctx.fillStyle='#fff';for(let i=0;i<50;i++){ctx.globalAlpha=.25+.5*((i*7+t/20)%3)/3;const sx=(i*137-cam*.05)%W;ctx.fillRect(sx<0?sx+W:sx,(i*53)%200,2,2);}ctx.globalAlpha=1;}
 if(st<3){ctx.save();ctx.fillStyle=st===2?'#dfe8ff':'#c8f0ff';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=40;ctx.beginPath();ctx.arc(st===2?560:640,st===2?120:100,st===2?52:36,0,7);ctx.fill();ctx.restore();}
 const ob=(sp,per,fn)=>{const off=cam*sp;for(let i=-1;i<W/per+2;i++)fn(i*per-off%per,i+Math.floor(off/per));};
 const r5=(n,m)=>((n%m)+m)%m;
 if(st===0){
  const tree=(x,h,c)=>{ctx.fillStyle=c;ctx.fillRect(x-4,GY-h*.3,8,h*.3);for(let k=0;k<3;k++){const w=38-k*8,y=GY-h*.3-k*h*.22;ctx.beginPath();ctx.moveTo(x-w,y);ctx.lineTo(x,y-h*.42);ctx.lineTo(x+w,y);ctx.fill();}};
  ob(.2,80,(x,n)=>tree(x+40,110+r5(n*37,5)*16,'#0a2a1e'));ob(.5,110,(x,n)=>tree(x+55,150+r5(n*53,5)*18,'#05160f'));
  ctx.fillStyle=S.ac;for(let i=0;i<18;i++){ctx.globalAlpha=.4+.5*Math.sin(t/20+i);ctx.fillRect(r5(i*97-cam*.4,W),150+r5(i*53,200)+Math.sin(t/30+i)*10,2,2);}ctx.globalAlpha=1;
 }else if(st===1){
  ob(.12,720,(x)=>{ctx.fillStyle=S.bg[1];[[20,70,260],[110,50,200],[170,110,150],[300,80,240],[400,160,130],[580,60,210]].forEach(([dx,w,h])=>{ctx.fillStyle=S.bg[1];ctx.fillRect(x+dx,GY-h,w,h);for(let c=0;c<w-6;c+=14)ctx.fillRect(x+dx+c,GY-h-8,8,8);ctx.fillStyle=S.ac;ctx.fillRect(x+dx+w/2-3,GY-h+24,6,12);});});
  ob(.5,170,(x)=>{ctx.fillStyle='#0b0618';ctx.fillRect(x,GY-80,160,80);for(let c=0;c<160;c+=40)ctx.fillRect(x+c,GY-92,24,12);ctx.fillStyle=S.ac;ctx.globalAlpha=.25;ctx.fillRect(x,GY-80,160,2);for(let r=GY-60;r<GY;r+=20)ctx.fillRect(x,r,160,1);ctx.globalAlpha=1;});
 }else if(st===2){
  const dt=(x,h)=>{ctx.strokeStyle='#0a1018';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x,GY);ctx.lineTo(x,GY-h);ctx.moveTo(x,GY-h*.6);ctx.lineTo(x-30,GY-h*.9);ctx.moveTo(x,GY-h*.7);ctx.lineTo(x+34,GY-h);ctx.moveTo(x-30,GY-h*.9);ctx.lineTo(x-44,GY-h*.85);ctx.stroke();};
  const gv=(x,n,c)=>{const h=40+r5(n*17,4)*8;ctx.fillStyle=c;if(r5(n,3)===0){ctx.fillRect(x,GY-h,24,h);ctx.beginPath();ctx.arc(x+12,GY-h,12,Math.PI,0);ctx.fill();}else if(r5(n,3)===1){ctx.fillRect(x+9,GY-h-14,6,h+14);ctx.fillRect(x,GY-h,24,6);}else ctx.fillRect(x,GY-h*.7,30,h*.7);};
  ob(.25,260,(x,n)=>dt(x+130,170+r5(n*31,3)*30));ob(.4,120,(x,n)=>gv(x+30,n,'#111a26'));ob(.7,90,(x,n)=>gv(x+20,n,'#070c14'));
  ctx.fillStyle='rgba(160,255,220,.06)';for(let i=0;i<3;i++)ctx.fillRect(0,GY-50+i*14+Math.sin(t/60+i)*6,W,18);
 }else if(st===3){
  ctx.fillStyle=S.ac;ctx.globalAlpha=.08;for(let y=40;y<GY;y+=34)ctx.fillRect(0,y,W,1);ctx.globalAlpha=1;
  ob(.5,220,(x,n)=>{ctx.fillStyle='#2a0c1c';ctx.fillRect(x+20,40,44,GY-40);ctx.fillStyle='#3a1228';ctx.fillRect(x+14,40,56,14);ctx.fillRect(x+14,GY-16,56,16);
   ctx.fillStyle='#4a2010';ctx.fillRect(x+39,206,6,18);ctx.save();ctx.fillStyle='#ffa030';ctx.shadowColor='#ff6010';ctx.shadowBlur=24;ctx.beginPath();ctx.ellipse(x+42,198,6,14+Math.sin(t/4+n)*3,0,0,7);ctx.fill();ctx.restore();
   ctx.fillStyle='#8a1030';ctx.fillRect(x+130,60,36,110);ctx.beginPath();ctx.moveTo(x+130,170);ctx.lineTo(x+148,190);ctx.lineTo(x+166,170);ctx.fill();ctx.fillStyle=S.ac;ctx.fillRect(x+143,90,10,10);});
 }else{
  for(let l=1;l<=2;l++){ctx.fillStyle=l===1?S.bg[1]:'#00000055';
   for(let i=-1;i<14;i++){const sp=l*.25,bx=i*120-(cam*sp)%120,hh=60+((i+Math.floor(cam*sp/120))*53%120+120)%120*(l===1?1.3:.8);
    ctx.fillRect(bx,GY-hh,70,hh);ctx.fillStyle=S.ac;ctx.globalAlpha=.5;ctx.fillRect(bx,GY-hh,70,2);ctx.fillRect(bx+10,GY-hh+14,6,6);ctx.globalAlpha=1;ctx.fillStyle=l===1?S.bg[1]:'#00000055';}}
 }
 ctx.fillStyle=['#0a1a10','#140e20','#10161c','#180a10','#10081c'][st];ctx.fillRect(0,GY,W,H-GY);ctx.fillStyle=S.ac;ctx.fillRect(0,GY,W,3);
 ctx.globalAlpha=.25;for(let i=0;i<20;i++)ctx.fillRect(i*50-(cam%50),GY+10,2,H);ctx.globalAlpha=1;
}
/* ---------- Sprites pixel art (gerados por código) ---------- */
const SPR={};
function mk(rows,pal,s){const c=document.createElement('canvas');c.width=rows[0].length*s;c.height=rows.length*s;const g=c.getContext('2d');rows.forEach((r,y)=>[...r].forEach((ch,x)=>{if(pal[ch]){g.fillStyle=pal[ch];g.fillRect(x*s,y*s,s,s);}}));return c;}
function spr(key,rows,pal,s,flash){key+=flash?'F':'';if(!SPR[key]){if(flash){pal=Object.fromEntries(Object.keys(pal).map(k=>[k,'#fff']));}SPR[key]=mk(rows,pal,s);}return SPR[key];}
const UP=["...HHHH....","..HHHHHH...",".HHssvvvH..",".Hhsssss...",".H..sss....","...ppwpp...","..pppcppp..",".sppPcPpps.",".s.ppcpp.s.",".s.pPcPp.s.","...cccccc..","...pppppp.."];
const ATK=[".sppPcPppss",".s.ppcppsss",".s.pPcPpsss"];
const LEG={
 idle:["..pp..pp...","..pp..pp...","..pP..Pp...","..pP..Pp...","..cc..cc...","..pp..pp...","..pp..pp...","..kk..kk...",".kkk..kkk.."],
 a:["..pp...pp..",".pp.....pp.",".pP.....Pp.",".pP.....Pp.",".cc.....cc.",".pp.....pp.","pp.......pp","kk.......kk","kkk.....kkk"],
 b:["...pppp....","...pPPp....","...pPPp....","...pppp....","...cccc....","...pppp....","..pp..pp...","..kk..kk...",".kkk..kkk.."]};
const SPAL={H:CY,h:'#00a8c0',s:'#f2c9a0',v:'#ff3cf2',p:'#a020f0',P:'#5a1090',w:'#e8d0ff',c:CY,k:'#1a0a30'};
const WALK=["....kkkkkk....","...kppppppk...","..kppppppppk..","..kpyyppppyk..","..kppppppppk..","..kpkkkkkkpk..","...kppppppk...","..kkpcppcpkk..",".kppkppppkppk.",".kppkppppkppk.","..kk.kppk.kk..","....kppppk....","...kkk..kkk...","..kkk....kkk..","..kk......kk.."];
const FLY=["..c........c..",".cc..kkkk..cc.","ccc.kppppk.ccc","cc.kppppppk.cc","c..kpyppypk..c","...kppppppk...","...kpkkkkpk...","....kppppk....",".....kppk.....","......kk......"];
const BOSS=[
["..kkkkkkkk..",".kppppppppk.",".kpyppppypk.",".kppppppppk.","kkpppccpppkk","kppppccppppk","kppkppppkppk","kkkkppppkkkk","..kppppppk..","..kppkkppk..","..kppkkppk..",".kkkk..kkkk."],
["...c....c...","..ckk..kkc..","..kppkkppk..",".kppppppppk.",".kpyppppypk.",".kppppppppk.",".kpkkkkkkpk.","..kpwpwpwpk.","..kppppppk..","..kppcppck..","...kppppk...","...kkppkk..."],
["....kkkk....","...kppppk...","..kpyppypk..","..kppppppk..","...kkkkkk...",".kkppccppkk.","kpppccccpppk","kp.pcppcp.pk","kp.pppppp.pk","...kppppk...","..kpp..ppk..",".kkk....kkk."],
["....cc......","...kkkkk....","..kppppppk..","..kpyyyypk..","..kppppppk..",".kkkppppkkk.","kppkcppckppk","kppkppppkppk","kppkppppkppk",".kk.kppk.kk.","...kppppk...","..kkk..kkk.."],
["k..kkkkkk..k","kk.kppppk.kk","kpkppppppkpk","kppppyyppppk","kpppyyyypppk","kppppyyppppk","kpcppppppcpk",".kppppppppk.",".kpkkkkkkpk.","..kppwwppk..","..kppppppk..","...kkkkkk..."]];
function drawPlOld(){
 if(pl.inv>0&&(t>>2)%2)return;
 let leg=!pl.gr||Math.abs(pl.vx)>.6?((t>>3)%2?LEG.a:LEG.b):LEG.idle;
 if(!pl.gr)leg=LEG.a;
 const up=disk?UP.slice(0,7).concat(ATK,UP.slice(10)):UP;
 const img=spr('pl'+(disk?'A':'')+(leg===LEG.idle?'i':leg===LEG.a?'a':'b'),up.concat(leg),SPAL,2);
 ctx.save();ctx.translate(pl.x-cam+pl.w/2,pl.y);ctx.scale(pl.f,1);
 ctx.shadowColor=CY;ctx.shadowBlur=8;ctx.drawImage(img,-11,0);ctx.restore();
}
function drawEnOld(e){
 const x=e.x-cam,sx=pl.x<e.x?-1:1,fl=e.fl>0;
 ctx.save();
 if(e.fly){
  const pal={p:'#17a8c0',c:CY,y:'#ffe000',k:'#06202a'};
  ctx.translate(x+14,e.y+5);ctx.scale(sx,1);ctx.drawImage(spr('fly'+(e.stun>0?'s':''),FLY,e.stun>0?{p:'#777',c:'#999',y:'#333',k:'#222'}:pal,2,fl),-14,Math.sin(t/3)*2);
 }else{
  const pal=e.stun>0?{p:'#777',c:'#999',y:'#333',k:'#222'}:{p:'#b030a0',c:'#ff3cf2',y:'#ffe000',k:'#1a0a20'};
  ctx.translate(x+14,e.y);ctx.scale(sx,1);ctx.drawImage(spr('walk'+(e.stun>0?'s':''),WALK,pal,2,fl),-14,0);
 }
 ctx.restore();
 if(e.stun>0){ctx.fillStyle='#ff0';ctx.font='14px monospace';ctx.textAlign='left';ctx.fillText('✦',x+8,e.y-4);}
}
/* ---------- Sprites dos seus arquivos (CraftPix) ---------- */
const SH={saki_idle:[6,128,83],saki_run:[8,128,83],saki_atk:[6,128,83],saki_jump:[12,128,83],zombie:[12,66,92],skeleton:[12,71,92]};
const IMG={};for(const n in SH){const i=new Image();i.src=DATA[n];IMG[n]=i;}
const ok=n=>IMG[n]&&IMG[n].complete&&IMG[n].naturalWidth>0;
function drawPl(){
 if(!ok('saki_idle'))return drawPlOld();
 if(pl.inv>0&&(t>>2)%2)return;
 let n='saki_idle',f=(t>>4)%6;
 if(disk){n='saki_atk';f=Math.min(5,(t-disk.t0)/3|0);}
 else if(!pl.gr){n='saki_jump';f=Math.max(0,Math.min(11,Math.round((pl.vy+10)*11/20)));}
 else if(Math.abs(pl.vx)>.6){n='saki_run';f=(t>>3)%8;}
 const [cnt,fw,fh]=SH[n],S=.7;
 ctx.save();ctx.translate(pl.x-cam+pl.w/2,pl.y+pl.h);ctx.scale(pl.f,1);
 ctx.shadowColor=CY;ctx.shadowBlur=10;
 ctx.drawImage(IMG[n],f*fw,0,fw,fh,-fw*S/2,-fh*S,fw*S,fh*S);ctx.restore();
}
function drawEn(e){
 const n=stage%2?'skeleton':'zombie';
 if(e.fly||!ok(n))return drawEnOld(e);
 const [cnt,fw,fh]=SH[n],S=.5,f=e.stun>0?0:(t>>3)%cnt,sx=pl.x<e.x?-1:1;
 ctx.save();ctx.translate(e.x-cam+e.w/2,e.y+e.h);ctx.scale(-sx,1);
 if(e.stun>0)ctx.globalAlpha=.55;
 if(e.fl>0&&'filter' in ctx)ctx.filter='brightness(4)';
 ctx.drawImage(IMG[n],f*fw,0,fw,fh,-fw*S/2,-fh*S,fw*S,fh*S);ctx.restore();
 if(e.stun>0){ctx.fillStyle='#ff0';ctx.font='14px monospace';ctx.textAlign='left';ctx.fillText('✦',e.x-cam+8,e.y-4);}
}
function drawBoss(S){
 const b=boss,x=b.x-cam;
 const img=spr('boss'+stage,BOSS[stage],{p:S.bc,c:S.ac,k:'#10081c',y:'#ff1030',w:'#fff'},4,b.fl>0);
 ctx.save();
 if(S.sink){ctx.beginPath();ctx.rect(0,0,W,GY);ctx.clip();}
 ctx.shadowColor=S.ac;ctx.shadowBlur=14;
 if(b.f<0){ctx.translate(x+b.w,b.y);ctx.scale(-1,1);ctx.drawImage(img,0,0,b.w,b.h);}else ctx.drawImage(img,x,b.y,b.w,b.h);
 ctx.restore();
 if(S.final&&b.ph===2){ctx.strokeStyle='#ff1030';ctx.lineWidth=3;ctx.strokeRect(x-4,b.y-4,b.w+8,b.h+8);}
 ctx.fillStyle='#000a';ctx.fillRect(100,42,600,S.final?16:10);
 ctx.fillStyle=S.final?'#ff1030':S.ac;ctx.fillRect(102,44,596*Math.max(0,b.hp/b.max),S.final?12:6);
 ctx.fillStyle='#fff';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText(S.b.toUpperCase()+(S.final?(b.ph===2?' — FASE 2':' — FASE 1'):''),W/2,S.final?72:66);
}
function hud(){
 ctx.fillStyle='#000c';ctx.fillRect(0,0,W,34);ctx.fillStyle=P1;ctx.fillRect(0,34,W,2);
 ctx.font='bold 13px monospace';ctx.textAlign='left';ctx.fillStyle=CY;ctx.fillText('SAKI VERSO',10,22);
 ctx.fillStyle='#fff';ctx.fillText('SCORE '+String(score).padStart(7,'0'),120,22);
 ctx.fillText('HI '+String(Math.max(hi,score)).padStart(7,'0'),270,22);
 ctx.fillStyle='#ff3cf2';ctx.fillText('VIDAS '+Math.max(0,lives),420,22);
 ctx.fillStyle='#ff4060';ctx.fillText('♥'.repeat(Math.max(0,pl.hp)),500,22);
 ctx.fillStyle='#fff';ctx.fillText('FASE '+(stage+1)+'/5',570,22);
 ctx.fillStyle=CY;ctx.fillText('ESPADA Nv'+wlv,680,22);
}
function ctr(txt,y,size,col){ctx.font='bold '+size+'px monospace';ctx.textAlign='center';ctx.fillStyle=col;ctx.fillText(txt,W/2,y);}
function draw(){
 const S=STAGES[Math.min(stage,4)];
 if(state==='menu'){
  bg(STAGES[0],0);ctx.fillStyle='#000a';ctx.fillRect(0,0,W,H);
  ctx.shadowColor=P1;ctx.shadowBlur=20;ctr('SAKI VERSO',150,64,CY);ctx.shadowBlur=0;
  ctr('LÂMINA NEON',200,32,'#ff3cf2');
  ctr('Onde o Mundo Gamer e Tecnologia estão sempre On',240,14,'#fff');
  if((t>>5)%2)ctr('PRESS START',320,28,'#fff');
  ctr('Enter / Espaço / X / Start',350,13,'#aaa');ctr('HIGH SCORE '+String(hi).padStart(7,'0'),400,16,CY);return;
 }
 bg(S);
 for(const o of orbs){ctx.fillStyle='#ffe000';ctx.shadowColor='#ffe000';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(o.x-cam+9,o.y+9+Math.sin(t/8)*3,8,0,7);ctx.fill();ctx.shadowBlur=0;}
 for(const e of en){drawEn(e);if(e.mx>1&&!e.dead){ctx.fillStyle='#000a';ctx.fillRect(e.x-cam,e.y-9,e.w,4);ctx.fillStyle='#ff3060';ctx.fillRect(e.x-cam,e.y-9,e.w*Math.max(0,e.hp/e.mx),4);}}
 if(boss)drawBoss(S);
 for(const q of bul){ctx.fillStyle='#ff1030';ctx.fillRect(q.x-cam,q.y,q.w,q.h);}
 if(disk&&disk.box){const b=disk.box,cx=pl.x+pl.w/2-cam,age=t-disk.t0;ctx.save();ctx.globalAlpha=Math.max(0,1-(age-3)/12);
  ctx.strokeStyle=wlv>=3?'#ff3cf2':CY;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=16;ctx.lineWidth=7;ctx.beginPath();
  ctx.arc(cx,pl.y+pl.h*.5,b.w+10,pl.f>0?-1.1:Math.PI-1.1+0.0,pl.f>0?1.1:Math.PI+1.1);ctx.stroke();ctx.restore();}
 drawPl();
 for(const s of shs){ctx.save();ctx.translate(s.x-cam+7,s.y+7);ctx.rotate(s.r);ctx.fillStyle=s.ex?'#ffb000':'#e8f8ff';ctx.shadowColor=CY;ctx.shadowBlur=10;ctx.beginPath();for(let i=0;i<8;i++){const r=i%2?3:9,a=i*Math.PI/4;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fill();ctx.restore();}
 if(shout>0){ctx.font='bold 20px monospace';ctx.textAlign='center';ctx.fillStyle='#ff3cf2';ctx.fillText('HAA!',pl.x-cam+12,pl.y-6-(40-shout)*.4);}
 for(const p of parts){ctx.fillStyle=p.c;ctx.fillRect(p.x-cam,p.y,3,3);}
 hud();
 ctx.fillStyle='#000a';ctx.fillRect(10,42,85,8);ctx.fillStyle=energy>=100?'#fff':'#ff3cf2';ctx.fillRect(11,43,83*energy/100,6);
 ctx.font='10px monospace';ctx.textAlign='left';ctx.fillStyle='#fff';ctx.fillText(energy>=100?'ESPECIAL PRONTO: E / Shift':'ESPECIAL',10,64);
 ctx.textAlign='right';ctx.fillStyle=CY;ctx.fillText('PODER: '+PN[Math.min(4,stage)],790,64);
 if(flash>0){ctx.fillStyle='rgba(255,255,255,'+flash/20+')';ctx.fillRect(0,0,W,H);}
 if(state==='play'&&msgT>0){msgT--;ctr('ROUND '+(stage+1)+' — '+S.n.toUpperCase(),230,26,'#fff');if(bossOn)ctr('CHEFE: '+S.b.toUpperCase(),270,18,'#ff1030');else ctr('NOVO PODER: '+PN[stage],270,16,CY);}
 if(state==='clear'){ctx.fillStyle='#000a';ctx.fillRect(0,0,W,H);ctr('ROUND CLEAR',210,48,CY);ctr('Bônus +'+(2000+stage*1000),260,18,'#fff');}
 if(state==='pause'){ctx.fillStyle='#000b';ctx.fillRect(0,0,W,H);ctr('PAUSA',230,48,'#fff');ctr('P / Esc / Start para continuar',270,14,CY);}
 if(state==='over'){ctx.fillStyle='#000c';ctx.fillRect(0,0,W,H);ctr('GAME OVER',200,56,'#ff1030');ctr('Score '+score+'  ·  Recorde '+hi,250,18,'#fff');ctr('Enter / X / Start para reiniciar',300,16,CY);}
 if(state==='win'){ctx.fillStyle='#000c';ctx.fillRect(0,0,W,H);ctr('VITÓRIA!',190,56,CY);ctr('Saki Verso derrotou o Núcleo do Mal',240,18,'#fff');ctr('Score final '+score+'  ·  Recorde '+hi,280,16,'#ff3cf2');ctr('Pressione para voltar ao menu',330,14,'#aaa');}
}

/* ---------- Loop 60 FPS fixo ---------- */
let last=performance.now(),acc=0;
function loop(n){acc+=Math.min(100,n-last);last=n;while(acc>=1000/60){update();acc-=1000/60;}draw();requestAnimationFrame(loop);}

/* ---------- Site: tela cheia, mudo e pausa automática ---------- */
const frame=document.getElementById('stage');
function toggleFull(){
 if(!frame)return;
 if(document.fullscreenElement){document.exitFullscreen();}
 else if(frame.requestFullscreen){frame.requestFullscreen().catch(()=>{});}
}
addEventListener('keydown',e=>{if(e.code==='KeyF'&&!e.repeat)toggleFull();});
const bFull=document.getElementById('btn-full'),bMute=document.getElementById('btn-mute');
if(bFull)bFull.addEventListener('click',()=>{toggleFull();cv.focus();});
if(bMute)bMute.addEventListener('click',()=>{dispatchEvent(new KeyboardEvent('keydown',{code:'KeyM'}));bMute.setAttribute('aria-pressed',String(mute));bMute.textContent=mute?'Som desligado':'Som ligado';cv.focus();});
addEventListener('blur',()=>{if(state==='play')state='pause';});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')state='pause';});
cv.addEventListener('pointerdown',()=>cv.focus());
startStage();requestAnimationFrame(loop);
